from typing import List, Tuple

def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    numbers.sort()
    closest_num1 = numbers[0]
    closest_num2 = numbers[1]
    for num in numbers[2:]:
        if abs(num - closest_num1) < abs(num - closest_num2):
            closest_num2 = num
        else:
            closest_num1 = num
            closest_num2 = closest_num1 + 1 if num != closest_num1 else num
    return (closest_num1, closest_num2)

