def find_zero(xs):
    def is_even(n):
        return n % 2 == 0

    def divisors(n):
        return [i for i in range(1, n + 1) if n % i == 0]

    def rational_roots(xs):
        constant = xs[-1]
        leading = xs[0]
        div_constant = divisors(constant)
        div_leading = divisors(leading)
        return [p / q for p in div_constant for q in div_leading]

    def synthetic_division(xs, root):
        result = [xs[0]]
        for i in range(len(xs) - 1):
            result.append(result[-1] * root + xs[i + 1])
        return result

    if not is_even(len(xs)):
        raise ValueError("Polynomial must have an even number of coefficients")

    roots = rational_roots(xs)
    for root in roots:
        if synthetic_division(xs, root)[-1] == 0:
            return root
    raise ValueError("No rational root found")

