import math

def closest_integer(value):
    value = float(value)
    rounded_value = round(value)
    if abs(value - rounded_value) == abs(value - math.ceil(value)):
        return math.ceil(value)
    elif abs(value - rounded_value) == abs(value - math.floor(value)):
        return math.floor(value)
    else:
        return rounded_value

